-- Store the finalized target-specific questionnaire catalog without activating a period or roster.
-- Student accounts cannot see these banks until a period instrument mapping and matching assignments exist.
-- Apply once through migration history; inspect state before any manual retry after partial execution.

alter table public.question_banks
  add column target_type text not null default 'subject_teacher'
    check (target_type in ('subject_teacher','homeroom_adviser','homeroom_program')),
  add column rating_labels jsonb not null default '{"1":"Strongly Disagree","2":"Disagree","3":"Neutral","4":"Agree","5":"Strongly Agree"}'::jsonb;

alter table public.question_items
  add column section_title text,
  add column section_position smallint not null default 1 check (section_position > 0),
  add column rating_max smallint not null default 5 check (rating_max in (4,5));

alter table public.question_items drop constraint if exists question_items_response_type_check;
alter table public.question_items add constraint question_items_response_type_check
  check (response_type in ('likert_4','likert_5','text'));
alter table public.question_items drop constraint if exists question_items_section_key_check;
alter table public.question_items add constraint question_items_section_key_check
  check (length(btrim(section_key)) > 0);
alter table public.question_items drop constraint if exists question_items_check;
alter table public.question_items add constraint question_items_response_contract_check
  check ((response_type='text' and use_for_rci=false)
      or (response_type in ('likert_4','likert_5') and section_key <> 'qualitative_feedback'));

-- Qualitative answers are required text responses. Phrases such as "Not applicable"
-- remain literal text in text_value; they are not converted into ratings or flags.


do $$
declare
  instrument jsonb;
  level_code text;
  section_data jsonb;
  item_data jsonb;
  bank_id bigint;
begin
  for instrument in select value from jsonb_array_elements($instrument_seed$[{"target_type": "subject_teacher", "title": "Subject Teacher Evaluation", "rating_labels": {"1": "Strongly Disagree", "2": "Disagree", "3": "Neutral", "4": "Agree", "5": "Strongly Agree"}, "sections": [{"section_key": "practice", "section_title": "A. Teaching Practice and Instructional Delivery", "section_position": 1, "items": [{"stable_key": "SUBJECT_TEACHER_PRACTICE_01", "prompt": "My teacher clearly explains lesson objectives, instructions, and content, connecting lessons to real-life situations or other subjects.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_02", "prompt": "My teacher uses different teaching strategies and activities that help me understand and learn the lesson.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_03", "prompt": "My teacher asks thought-provoking questions, values the questions we ask, and gives us chances to explain our own ideas, lead discussions, and come up with our own solutions.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_04", "prompt": "My teacher connects meaningfully the activities in Canvas/online tasks.", "response_type": "likert_5", "position": 4, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_05", "prompt": "My teacher communicates clearly (through language, tone, and gestures) in a way I can understand.", "response_type": "likert_5", "position": 5, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_06", "prompt": "My teacher provides learning materials that are useful, well-organized, and easy to access.", "response_type": "likert_5", "position": 6, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_07", "prompt": "My teacher gives assessments/activities that match what was taught and can be reasonably finished within the given time.", "response_type": "likert_5", "position": 7, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_PRACTICE_08", "prompt": "My teacher gives timely and specific feedback on my work that helps me improve.", "response_type": "likert_5", "position": 8, "rating_max": 5, "is_required": true}]}, {"section_key": "classroom", "section_title": "B. Classroom Environment and Learning Experience", "section_position": 2, "items": [{"stable_key": "SUBJECT_TEACHER_CLASSROOM_01", "prompt": "My teacher starts and ends class on time, comes prepared, and stays fully present and engaged throughout.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_02", "prompt": "My teacher checks attendance regularly and follows up when I am absent.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_03", "prompt": "My teacher treats all students fairly, with respect and care, and creates a safe space where I feel comfortable to participate, ask questions, and take risks.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_04", "prompt": "When there is misbehavior, my teacher handles it in a way that helps students reflect and improve, rather than just punish.", "response_type": "likert_5", "position": 4, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_05", "prompt": "My teacher adjusts lessons and activities to fit different students' needs, abilities, and backgrounds.", "response_type": "likert_5", "position": 5, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_06", "prompt": "My teacher connects our lessons to FEU's Vision, Mission, and Core Values (Fortitude, Excellence, Uprightness).", "response_type": "likert_5", "position": 6, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_CLASSROOM_07", "prompt": "I feel motivated to learn and participate because of how my teacher teaches and treats the class.", "response_type": "likert_5", "position": 7, "rating_max": 5, "is_required": true}]}, {"section_key": "self", "section_title": "Student Self-Evaluation", "section_position": 3, "items": [{"stable_key": "SUBJECT_TEACHER_SELF_01", "prompt": "I always arrive on time and regularly for class.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_SELF_02", "prompt": "I actively participate in class discussions, asking questions and engaging with the material.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_SELF_03", "prompt": "I collaborate with classmates when working on class activities/subject requirements.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_SELF_04", "prompt": "I turn in my activities and assessments on time and in good quality.", "response_type": "likert_5", "position": 4, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_SELF_05", "prompt": "I exerted a lot of effort and dedication in studying for this class.", "response_type": "likert_5", "position": 5, "rating_max": 5, "is_required": true}]}, {"section_key": "feedback", "section_title": "Qualitative Feedback", "section_position": 4, "items": [{"stable_key": "SUBJECT_TEACHER_FEEDBACK_01", "prompt": "What strategies and practices did you appreciate the most about your teacher?", "response_type": "text", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_FEEDBACK_02", "prompt": "What constructive suggestions can you give to help your teacher handle students or teach better?", "response_type": "text", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "SUBJECT_TEACHER_FEEDBACK_03", "prompt": "Overall, how was your learning experience with your teacher?", "response_type": "text", "position": 3, "rating_max": 5, "is_required": true}]}]}, {"target_type": "homeroom_adviser", "title": "Homeroom Adviser Evaluation", "rating_labels": {"1": "Strongly Disagree", "2": "Disagree", "3": "Neutral", "4": "Agree", "5": "Strongly Agree"}, "sections": [{"section_key": "fortitude", "section_title": "A. Fortitude — Resilience — Showing Up", "section_position": 1, "items": [{"stable_key": "HOMEROOM_ADVISER_FORTITUDE_01", "prompt": "My HRA regularly checks student attendance and proactively follows up on absences.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_FORTITUDE_02", "prompt": "My HRA arrives prepared for homeroom sessions and begins and ends them on time.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_FORTITUDE_03", "prompt": "My HRA maintains an active and engaged presence throughout homeroom sessions.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}]}, {"section_key": "excellence", "section_title": "B. Excellence — Curiosity — Asking Thoughtful Questions", "section_position": 2, "items": [{"stable_key": "HOMEROOM_ADVISER_EXCELLENCE_01", "prompt": "My HRA intentionally incorporates and elaborates on thoughtful questions during homeroom sessions.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_EXCELLENCE_02", "prompt": "My HRA ensures that multiple students are intentionally invited to explain, challenge, and refine ideas, making student thinking visible during classroom discussions.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_EXCELLENCE_03", "prompt": "My HRA actively encourage students to ask questions. Recognize insightful inquiries, and reinforce questioning as a valued habit.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}]}, {"section_key": "uprightness", "section_title": "C. Uprightness — Integrity — Owning Actions and Making Things Right", "section_position": 3, "items": [{"stable_key": "HOMEROOM_ADVISER_UPRIGHTNESS_01", "prompt": "My HRA addresses student misbehavior fairly and promotes learning, reflection, and personal growth.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_UPRIGHTNESS_02", "prompt": "My HRA consistently follows through on classroom expectations, agreements, and reminders.", "response_type": "likert_5", "position": 2, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_UPRIGHTNESS_03", "prompt": "My HRA models accountability by acknowledging mistakes or areas for improvement and making appropriate adjustments.", "response_type": "likert_5", "position": 3, "rating_max": 5, "is_required": true}]}, {"section_key": "overall", "section_title": "Overall Evaluation", "section_position": 4, "items": [{"stable_key": "HOMEROOM_ADVISER_OVERALL_01", "prompt": "Overall, my HRA effectively facilitates homeroom sessions and has been effective in guiding me academically and supporting my personal development.", "response_type": "likert_5", "position": 1, "rating_max": 5, "is_required": true}]}, {"section_key": "feedback", "section_title": "Qualitative Feedback", "section_position": 5, "items": [{"stable_key": "HOMEROOM_ADVISER_FEEDBACK_01", "prompt": "What are the most commendable characteristics of your homeroom adviser?", "response_type": "text", "position": 1, "rating_max": 5, "is_required": true}, {"stable_key": "HOMEROOM_ADVISER_FEEDBACK_02", "prompt": "What are the aspects of your homeroom adviser that need improvement?", "response_type": "text", "position": 2, "rating_max": 5, "is_required": true}]}]}, {"target_type": "homeroom_program", "title": "Homeroom Program Evaluation", "rating_labels": {"1": "Strongly Disagree", "2": "Disagree", "3": "Agree", "4": "Strongly Agree"}, "sections": [{"section_key": "fortitude", "section_title": "1. Fortitude — Resilience — Showing Up", "section_position": 1, "items": [{"stable_key": "HOMEROOM_PROGRAM_FORTITUDE_01", "prompt": "The program helped me become more consistent in attending and actively participating in homeroom sessions.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_FORTITUDE_02", "prompt": "The program encouraged me to be present, engaged, and prepared during homeroom activities.", "response_type": "likert_4", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_FORTITUDE_03", "prompt": "The program helped me become more responsible in showing up and participating meaningfully in school activities.", "response_type": "likert_4", "position": 3, "rating_max": 4, "is_required": true}]}, {"section_key": "excellence", "section_title": "2. Excellence — Curiosity — Asking Thoughtful Questions", "section_position": 2, "items": [{"stable_key": "HOMEROOM_PROGRAM_EXCELLENCE_01", "prompt": "The program encouraged me to ask meaningful and reflective questions during discussions.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_EXCELLENCE_02", "prompt": "The program helped me become more confident in expressing my thoughts, analyzing perspectives, and evaluating ideas critically.", "response_type": "likert_4", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_EXCELLENCE_03", "prompt": "The program helped me develop curiosity and deeper thinking about academic, personal, and social topics.", "response_type": "likert_4", "position": 3, "rating_max": 4, "is_required": true}]}, {"section_key": "uprightness", "section_title": "3. Uprightness — Integrity — Owning Actions and Making Things Right", "section_position": 3, "items": [{"stable_key": "HOMEROOM_PROGRAM_UPRIGHTNESS_01", "prompt": "The program helped me become more accountable for my actions and decisions.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_UPRIGHTNESS_02", "prompt": "The program helped me learn the importance of acknowledging mistakes and taking steps to correct them.", "response_type": "likert_4", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_UPRIGHTNESS_03", "prompt": "The program provided opportunities for me to reflect on my actions and make better choices when faced with challenges.", "response_type": "likert_4", "position": 3, "rating_max": 4, "is_required": true}]}, {"section_key": "platform", "section_title": "4. Shared Platform — HRA and Student-led Sessions", "section_position": 4, "items": [{"stable_key": "HOMEROOM_PROGRAM_PLATFORM_01", "prompt": "The Shared Platform helped make homeroom sessions more organized, purposeful, and responsive to student needs.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_PLATFORM_02", "prompt": "The Shared Platform encouraged collaboration, active participation, and the sharing of ideas among classmates.", "response_type": "likert_4", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_PLATFORM_03", "prompt": "The Shared Platform supported student reflection, feedback, and communication with the homeroom adviser.", "response_type": "likert_4", "position": 3, "rating_max": 4, "is_required": true}]}, {"section_key": "structure", "section_title": "5. Program Structure and Implementation", "section_position": 5, "items": [{"stable_key": "HOMEROOM_PROGRAM_STRUCTURE_01", "prompt": "The structure of the Be Brave Homeroom Program effectively integrated Showing Up, Asking Thoughtful Questions, and Owning Actions & Making Things Right.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_STRUCTURE_02", "prompt": "The homeroom sessions were well-organized, relevant, and engaging.", "response_type": "likert_4", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_STRUCTURE_03", "prompt": "The duration and pacing of the homeroom sessions were sufficient to support student formation and reflection.", "response_type": "likert_4", "position": 3, "rating_max": 4, "is_required": true}]}, {"section_key": "overall", "section_title": "6. Overall Experience", "section_position": 6, "items": [{"stable_key": "HOMEROOM_PROGRAM_OVERALL_01", "prompt": "Overall, the Be Brave Homeroom Program has significantly contributed to making the school a safe space for me, where I am able to consistently show up, ask thoughtful questions, and take ownership of my actions, while also helping me support others with resilience in adversity, a commitment to continuous growth, and the courage to do what is right even when it is difficult.", "response_type": "likert_4", "position": 1, "rating_max": 4, "is_required": true}]}, {"section_key": "feedback", "section_title": "Qualitative Feedback", "section_position": 7, "items": [{"stable_key": "HOMEROOM_PROGRAM_FEEDBACK_01", "prompt": "What topics and activities do you like most about your homeroom?", "response_type": "text", "position": 1, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_FEEDBACK_02", "prompt": "What topics and activities do you like least about your homeroom?", "response_type": "text", "position": 2, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_FEEDBACK_03", "prompt": "Do you have any topic/activity suggestions that you want to include in future homeroom sessions?", "response_type": "text", "position": 3, "rating_max": 4, "is_required": true}, {"stable_key": "HOMEROOM_PROGRAM_FEEDBACK_04", "prompt": "Additional Comments:", "response_type": "text", "position": 4, "rating_max": 4, "is_required": true}]}]}]$instrument_seed$::jsonb) as seed_rows(value)
  loop
    foreach level_code in array array['JHS','SHS'] loop
      insert into public.question_banks(code,version,school_level,title,target_type,rating_labels)
      values (
        case instrument->>'target_type'
          when 'subject_teacher' then format('faculty-evaluation-%s',lower(level_code))
          when 'homeroom_adviser' then format('homeroom-adviser-evaluation-%s',lower(level_code))
          when 'homeroom_program' then format('homeroom-program-evaluation-%s',lower(level_code))
        end,
        case when instrument->>'target_type'='subject_teacher' then 2 else 1 end,
        level_code,instrument->>'title',instrument->>'target_type',instrument->'rating_labels')
      returning id into bank_id;
      for section_data in select value from jsonb_array_elements(instrument->'sections') as section_rows(value)
      loop
        for item_data in select value from jsonb_array_elements(section_data->'items') as item_rows(value)
        loop
          insert into public.question_items(question_bank_id,stable_key,section_key,section_title,
            section_position,prompt,response_type,position,is_required,use_for_rci,rating_max)
          values (bank_id,item_data->>'stable_key',section_data->>'section_key',section_data->>'section_title',
            (section_data->>'section_position')::smallint,item_data->>'prompt',item_data->>'response_type',
            (item_data->>'position')::smallint,(item_data->>'is_required')::boolean,false,
            (item_data->>'rating_max')::smallint);
        end loop;
      end loop;
      update public.question_banks set status='published',published_at=now() where id=bank_id;
    end loop;
  end loop;
end;
$$;

-- Period mappings are configured after an approved target roster and period exist.
-- This avoids attaching the new instruments to pilot periods automatically.
